-- 演示库 torrent_files 回填（静态生成，勿手改）：
-- 为每条已过审演示种子生成合法 .torrent 原始字节，使 /torrents/{id}/download 可用。
-- info 字典 = length + name(UTF-8 bencode) + piece length + pieces(40B)；
-- info_hash 规则与 0018_demo_data（md5(name)）对齐；announce 指向自研 tracker。
-- 幂等：仅回填缺失行。
INSERT INTO torrent_files (torrent_id, raw)
SELECT 1, decode('','hex')
FROM torrents t WHERE t.id = 1
  AND NOT EXISTS (SELECT 1 FROM torrent_files f WHERE f.torrent_id = 1);

